B=[['拉丁 pro- + crastinus（来自 cras）','向前 + 属于明天的（明天）'],['拉丁 procrastinare','把事往明天推']]
W=[
E('procrastinate','英 /prəʊˈkræstɪneɪt/；美 /proʊˈkræstəneɪt/','拖延；迟迟不做','今天能开始，却把任务推到“明天”；明天来了，又想再推一天。','核心来自拉丁 pro- 向前 + crastinus 明天的。英语动词可解释为从 procrastination 逆构，或取拉丁 procrastinatus 分词形式；不是把 pro- 翻成赞成就完事。',B+[['英语 procrastinate','经拉丁形式或由先有名词逆构 → 拖延']],'常不接宾语：Stop procrastinating.；也可说 procrastinate on a task。它往往含有本该做却拖着的意思，不只是因为列车晚点等外界原因造成延迟。','stop procrastinating；procrastinate on；tend to procrastinate。','postpone 可以是合理地重新安排日期；procrastinate 更容易表示不愿面对或一直迟迟不动手。但一个词不能直接诊断拖延原因。',('I tend to procrastinate when I do not know where to start.','不知道从哪里开始时，我就容易拖延。'),('Stop procrastinating and write the first sentence.','别再拖了，先写出第一句话。'),sources=['https://www.etymonline.com/word/procrastinate']),
E('procrastination','英 /prəˌkræstɪˈneɪʃən/；美 /proʊˌkræstəˈneɪʃən/','拖延；拖着不做的行为','任务没有往前走，截止日期却在往前走。','经法语 procrastination 或直接来自拉丁 procrastinatio，把事情日复一日往后推的动作名词；英语名词记录早于现在常见的动词形式。',B+[['拉丁 procrastinatio → 法语／英语 procrastination','反复推迟的行为']],'通常不可数：a habit of procrastination 是拖延的习惯。中文口语常说“拖延症”，但英文这个普通名词本身不是某种疾病诊断的名称。','avoid procrastination；a habit of procrastination；procrastination over a decision。','procrastination 讲拖延行为；procrastinator 讲有这种习惯的人。不要把词尾 -ation 当成能证明英语动词一定先出现的证据。',('A clear first step helped me reduce procrastination.','把第一步想清楚，帮我减少了拖延。'),('After weeks of procrastination, he finally sent the application.','拖了好几个星期后，他终于提交了申请。'),sources=['https://www.etymonline.com/word/procrastination']),
E('procrastinator','英 /prəʊˈkræstɪneɪtə/；美 /proʊˈkræstəneɪtər/','爱拖延的人','不是任务自己被挪走，而是那个人总说“等一会儿再做”。','procrastinate + -or，构成人的名词；英语用拉丁式的施事者词尾形成。',B+[['英语 procrastinate + -or → procrastinator','拖延 → 常拖延的人']],'可以自嘲 I am a terrible procrastinator，也可以客观描述习惯。称呼别人时语气可能带批评，不必把一次延迟就上升成这个人的固定性格。','a habitual procrastinator；a chronic procrastinator；a terrible procrastinator。','procrastinator 不是 slow worker 的简单同义词：工作做得慢，与迟迟不肯开始或推进，是两回事。',('I am a procrastinator when it comes to sorting old papers.','一说到整理旧文件，我就爱拖。'),('Even a habitual procrastinator can finish a small task today.','即使是经常拖延的人，今天也可以先完成一件小任务。'),sources=['https://www.etymonline.com/word/procrastinator','https://en.wiktionary.org/wiki/procrastinator'])
]
ROOT=dict(id='C1130',meaning='向前；提前；代替、代表',core='PRO = FORWARD',image='朝前推一步：可以把船往前推，也可以把准备提前做；若把任务推到明天，却成了拖延。',intro='本页以拉丁 pro- 为主，先抓“在前、向前”的空间画面，再看它怎样走向提前安排、代表或代替。它的含义随历史组合而变，不能见到 pro- 就一律翻成专业或赞成。',forms='pro- 在 propel 中是向前，在 provide 的历史拆解中是预先，在 pronoun 中是代替。希腊语也有同源的 pro-，但每个英语词的借入路线要分别看；这里不把二者混成同一直接来源。',branches=[['朝前推进','propel、propulsion、propeller、propellant、proceed、progress、project、promote'],['把事情先放到前面','provide、proclaim、provoke'],['代替与往后推迟','pronoun、procrastinate、procrastination、procrastinator']],contrasts='procrastinate 的“向前”是在时间线上把事情往未来推，并非积极推进工作。pro 作为专业人士的简称另有 professional 的缩略背景，不要倒灌进所有古典词。',practice='The plan will not progress if we keep procrastinating.\n\n如果我们一直拖延，计划就不会有进展。',words=[x['word'] for x in W]+['propel','propulsion','propeller','propellant','proceed','progress','project','promote','provide','proclaim','provoke','pronoun'],exclude={})
